/** Deep-merges auto-generated leaf coverage (base) under hand-curated overrides (win on conflict). */
function deepMergeLocale(base: any, override: any): any {
  if (override === undefined || override === null) return base;
  if (typeof override !== "object" || Array.isArray(override)) return override;
  if (typeof base !== "object" || base === null || Array.isArray(base)) return override;
  const out: any = { ...base };
  for (const key of Object.keys(override)) {
    out[key] = deepMergeLocale(base[key], override[key]);
  }
  return out;
}

/** Same key tree as English; leaf strings widened (en catalogs use `as const`). */
type StringifyLeaves<T> = T extends string
  ? string
  : T extends object
    ? { [K in keyof T]: StringifyLeaves<T[K]> }
    : T;

type Catalog = StringifyLeaves<typeof enResources>;

/** Allow locales to lag new English keys; runtime merges with `en` and i18n falls back. */
type LocaleCatalog = { [K in keyof Catalog]: Partial<Catalog[K]> & Record<string, unknown> };

